const res = phi.js(() => {
  // find the expanded answer panel for the lost item question
  const out = [];
  document.querySelectorAll('h1,h2,h3,h4,p,li,a').forEach(el => {
    const t = (el.innerText || '').trim();
    if (t && /lost/i.test(t)) out.push({ tag: el.tagName, cls: el.className, text: t.slice(0, 800), href: el.getAttribute('href') || '' });
  });
  return out.slice(0, 40);
});
return res;

const res = phi.js(() => {
  const out = [];
  document.querySelectorAll('a').forEach(a => {
    const t = (a.innerText || '').trim();
    if (/form/i.test(t) || /lost/i.test(a.getAttribute('href') || '')) out.push({ text: t.slice(0,120), href: a.getAttribute('href') || '' });
  });
  return out.slice(0, 30);
});
phi.keep("lostitem", {
  question: "What do I do if I lost an item on the bus?",
  answer: "If an item is lost on a bus, a lost item inquiry must be reported to our lost and found department by filling out this form. Once you've submitted the necessary information on the lost item, it will be entered into our system for processing by our lost and found department. Our lost and found department responds to all loss inquiries. The time frame of response may take several days as an investigation to find the lost item must be completed. Megabus makes every attempt to return lost items to their rightful owners and will assist with retrieval to the best of our ability.",
  source: "https://us.megabus.com/help"
});
return res;

