const info = phi.goto("https://us.megabus.com/help");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
// inspect the card element itself for its content
const cardInfo = phi.query("#card6862e544fb0a45db9c3b99c4d27dbde8", { limit: 3 });
const inner = phi.js(() => {
  const el = document.getElementById("card6862e544fb0a45db9c3b99c4d27dbde8");
  if (!el) return { found: false };
  const html = el.textContent.replace(/\s+/g, " ").trim();
  return { found: true, tag: el.tagName, cls: el.className, text: html.slice(0, 1200), visible: el.offsetParent !== null };
});
return { cardInfo, inner };
